#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

struct Request {
    std::string id;
    std::string model;
    double latency_ms;
};

int main() {
    std::vector<Request> requests = {
        {"r1", "model-A", 30.0},
        {"r2", "model-B", 10.0},
        {"r3", "model-A", 20.0}
    };

    std::sort(requests.begin(), requests.end(),
        [](const Request& a, const Request& b) {
            return a.latency_ms < b.latency_ms;
        });

    for (const Request& r : requests) {
        std::cout << r.id << " "
                  << r.model << " "
                  << r.latency_ms << "\n";
    }
}
